			return 150;
		}
	}

	// Session Number
	public static class SessionNumberTableColumn : AbstractProgramBasedDynamicTableColumn<VTMatch, Integer> {

		/* @Override */
		public string getColumnName() {
			return "Session ID";
		}

		/* @Override */
		public Integer getValue(VTMatch rowObject, Settings settings, Program program,
				ServiceProvider serviceProvider)
    {
			VTMatchSet matchSet = rowObject.getMatchSet();
			int id = matchSet.getID();
			if (id < 1) {
				return null;
			}
			return id;
		}

		/* @Override */
		public int getColumnPreferredWidth() {
			return 30;
		}
	}

	// Tag
	public static class TagTableColumn : AbstractProgramBasedDynamicTableColumn<VTMatch, string> {

		/* @Override */
		public string getColumnName() {
			return "Tag";
		}

		/* @Override */
		public string getValue(VTMatch rowObject, Settings settings, Program program,
				ServiceProvider serviceProvider)
    {
			VTMatchTag tag = rowObject.getTag();
			if (tag == null) {
				return null;
			}
			return tag.getName();
		}

		/* @Override */
		public int getColumnPreferredWidth() {
			return 100;
		}
	}

	public static class ImpliedMatchCountColumn : AbstractProgramBasedDynamicTableColumn<VTMatch, Integer> {

		/* @Override */
		public string getColumnName() {
			return "Votes";
		}

		/* @Override */
		public string getColumnDescription() {
			return "Votes - The number of references from previously accepted " +
				"matches that would suggest that this is a correct match";
		}

		/* @Override */
		public Integer getValue(VTMatch rowObject, Settings settings, Program program,
				ServiceProvider serviceProvider)
    {
			return rowObject.getAssociation().getVoteCount();
		}

		/* @Override */
		public int getColumnPreferredWidth() {
			return 30;
		}
	}

	public static class RelatedMatchCountColumn : AbstractProgramBasedDynamicTableColumn<VTMatch, Integer> {

		/* @Override */
		public string getColumnName() {
			return "# Conflicting";
		}

		/* @Override */
		public string getColumnDescription() {
			return "# Conflicting - The number of unique associations with either" +
				" the same source or same destination address";
		}

		/* @Override */
		public Integer getValue(VTMatch rowObject, Settings settings, Program program,
				ServiceProvider serviceProvider)
    {
			// subtract 1 here because the match itself is always counted in the results
			return rowObject.getAssociation().getRelatedAssociations().size() - 1;
		}

		/* @Override */
		public int getColumnPreferredWidth() {
			return 30;
		}
	}

	internal class _Anon_AbstractGColumnRenderer_1 : AbstractGColumnRenderer<>
	{

			/* @Override */
			public Component getTableCellRendererComponent(GTableCellRenderingData data) {

				JLabel label = (JLabel) base.getTableCellRendererComponent(data);

				object value = data.getValue();

				VTScore score = (VTScore) value;
				if (score == null) {
					label.setText("N/A");
				}
				else {
					label.setText(score.getFormattedScore());
				}

				label.setOpaque(true);

				return label;
			}

			/* @Override */
			public string getFilterString(VTScore t, Settings settings) {
				if (t == null) {
					return "N/A";
				}
				return t.getFormattedScore();
			}
		
	}


